// Defined only inside the original factory TU (NameObjFactory.cpp), inline there.
DashFruit::DashFruit(const char* pName) : StemFruit(pName) {}

// createNameObj<T> (new T(pName)) comes from NameObjFactory.hpp's unnamed namespace.
namespace {

    template < typename T >
    NameObj* createCenterOriginCube(const char* pName) {
        return new T(1, pName);
    }

    template < typename T >
    NameObj* createBaseOriginCube(const char* pName) {
        return new T(0, pName);
    }

    template < typename T >
    NameObj* createSphere(const char* pName) {
        return new T(2, pName);
    }

    template < typename T >
    NameObj* createBaseOriginCylinder(const char* pName) {
        return new T(3, pName);
    }

    template <> NameObj* createNameObj< Togepin >(const char* pName) { return new Togepin(pName, nullptr); }

    template <> NameObj* createNameObj< PoleObstacleParts >(const char* pName) { return new PoleObstacleParts(pName, 0, nullptr); }

    template <> NameObj* createNameObj< MorphItemNeoBee >(const char* pName) { return new MorphItemNeoBee("ハチオブジェ"); }

    template <> NameObj* createNameObj< MorphItemNeoFire >(const char* pName) { return new MorphItemNeoFire("ファイアオブジェ"); }

    template <> NameObj* createNameObj< MorphItemNeoHopper >(const char* pName) { return new MorphItemNeoHopper("ホッパーオブジェ"); }

    template <> NameObj* createNameObj< MorphItemNeoTeresa >(const char* pName) { return new MorphItemNeoTeresa("テレサオブジェ"); }

    [[noreturn]] void trapMissingClass(const char* pClass, const char* pName) {
        std::fprintf(stderr, "NameObjFactory: class %s (object \"%s\") has no native header yet\n", pClass, pName);
        std::abort();
    }

    [[noreturn]] void trapMissingPostCreation(const char* pFunction) {
        std::fprintf(stderr, "NameObjFactory: post-creation %s is not callable natively yet\n", pFunction);
        std::abort();
    }

}  // namespace

#include "../src/Game/NameObj/NameObjFactoryTables.inc"
#endif
